using System.Text.Encodings.Web;

internal static class ConfigurationShell
{
    public static string Render(string title, string content, string active)
    {
        string html = """
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__ · System Configuration</title><style>__CSS__</style></head><body><header class="topbar"><div class="cornerbars"><i></i><i></i></div><div class="brand"><span class="gear">✹</span><div><strong>System <em>Configuration</em></strong><small>KNOW WHAT IS REQUIRED. KNOW WHAT IS CONFIGURED.</small></div></div><div class="org"><b>Food For The Poor Jamaica</b><span>A More Hopeful Tomorrow</span></div><div class="site">FFP-JM</div><div class="clock" id="clock"></div><div class="user"><span>FW</span><div>Fitzroy Wright<small>IT Manager</small></div></div></header><div class="frame"><aside class="sidebar"><nav><a class="ops-return" href="http://localhost:5100/" title="Return to System Operations"><span>◀</span>Operations</a><a class="__APPS__" href="/"><span>▦</span>Applications</a><a class="__RUNBOOKS__" href="/runbooks"><span>▤</span>Runbooks</a><a href="/api/contracts"><span>◇</span>Contracts</a><a href="#"><span>⚙</span>Settings</a></nav><div class="sidefoot"><b>System<br>Configuration</b><small>v1.0.0</small></div></aside><main>__CONTENT__</main></div><footer><b>System Configuration</b><span>│</span><span>Integrated Operations for a More Reliable Tomorrow</span><div class="footright"><i></i> All Systems Operational &nbsp; │ &nbsp; Food For The Poor Jamaica &nbsp; │ &nbsp; v1.0.0</div></footer><script>const tick=()=>document.getElementById('clock').textContent=new Date().toLocaleString();tick();setInterval(tick,30000);const q=document.getElementById('search'),f=document.getElementById('statusFilter');const filterRows=()=>document.querySelectorAll('#apps tbody tr').forEach(r=>r.style.display=(!q||r.innerText.toLowerCase().includes(q.value.toLowerCase()))&&(!f||!f.value||r.innerText.toLowerCase().includes(f.value.toLowerCase()))?'':'none');if(q)q.addEventListener('input',filterRows);if(f)f.addEventListener('change',filterRows);</script></body></html>
""";
        return html
            .Replace("__TITLE__", HtmlEncoder.Default.Encode(title), StringComparison.Ordinal)
            .Replace("__CSS__", BaseCss + "\n" + GlossyCss.Value, StringComparison.Ordinal)
            .Replace("__APPS__", active == "applications" ? "active" : "", StringComparison.Ordinal)
            .Replace("__RUNBOOKS__", active == "runbooks" ? "active" : "", StringComparison.Ordinal)
            .Replace("__CONTENT__", content, StringComparison.Ordinal);
    }

    private const string BaseCss = """
:root{--bg:#00101d;--panel:#001827;--line:#15547b;--text:#eef6ff;--muted:#aac2d7;--blue:#087fff;--orange:#ffad31;--purple:#8e61ff;--green:#20d789;--amber:#ff9f0b}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#00101d;color:var(--text);font:14px/1.35 'Segoe UI',Arial,sans-serif}body{padding:0 5px}a{color:inherit;text-decoration:none}.topbar{height:84px;display:grid;grid-template-columns:70px minmax(360px,1fr) 220px 110px 220px 210px;align-items:center;border-bottom:2px solid #4180aa}.cornerbars{height:100%;display:flex;gap:7px;padding-top:18px}.cornerbars i:first-child{width:31px;height:54px;background:var(--orange);border-radius:26px 0 0}.cornerbars i:last-child{width:25px;height:54px;background:var(--purple)}.brand{display:flex;align-items:center;gap:14px}.gear{font-size:50px;color:#2ba9ff}.brand strong{font-size:34px;display:block}.brand em{font-style:normal;color:var(--orange)}.brand small{color:#42bdff;font-weight:800}.org{color:#5bc2ff;display:flex;flex-direction:column;font-size:16px}.site{background:#2727a6;border-left:18px solid var(--orange);border-radius:18px;padding:13px 18px;font-weight:800}.clock{border:1px solid #154c70;padding:14px}.user{display:flex;gap:10px;align-items:center;border:1px solid #154c70;border-radius:18px;padding:8px;color:#5bc2ff}.user>span{border:2px solid #209ef0;border-radius:50%;padding:9px}.user small{display:block}.frame{min-height:calc(100vh - 132px);border:1px solid #4c84a7;border-radius:25px;box-shadow:inset 0 0 24px #4db9ff44;display:grid;grid-template-columns:160px 1fr;overflow:hidden;margin-top:7px}.sidebar{background:#001b2e;border-right:1px solid #174f73;display:flex;flex-direction:column}.sidebar:before{content:'';height:63px}.sidebar a{display:flex;align-items:center;gap:17px;padding:16px;font-weight:700;font-size:16px}.sidebar a span{color:#36b9ff;font-size:25px}.sidebar a.active{background:var(--orange);color:#06111b;border-radius:0 9px 9px 0}.sidebar a.ops-return{margin:0 10px 12px 0;background:linear-gradient(180deg,#b99aff,#8e61ff 42%,#5430bd);color:#fff;border-radius:0 22px 22px 0;box-shadow:inset 0 2px 1px #ffffff70,0 3px 10px #0008}.sidebar a.ops-return span{color:#fff}.sidefoot{margin-top:auto;padding:25px;color:#59c0ff}.sidefoot small{display:block}main{padding:20px 10px;min-width:0}.page-head{padding:4px 12px 14px 40px;border-left:13px solid var(--purple);border-radius:18px}.page-head h1{font-size:31px;margin:0}.page-head p{margin:2px 0;color:#c1d4e4}.toolbar{display:flex;gap:10px;margin:10px 0}.toolbar input{flex:1}.toolbar input,.toolbar select,.toolbar button,.primary,dialog button{background:#00182a;color:white;border:1px solid #23618a;border-radius:6px;padding:11px}.primary{background:#087fff!important;font-weight:800}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin:14px 0}.metric{height:82px;border:1px solid #087fff;border-radius:5px;display:grid;grid-template-columns:55px 1fr;grid-template-rows:1fr 1fr;align-items:center;padding:8px;background:#002037}.metric span{grid-row:1/3;width:42px;height:42px;border-radius:50%;display:grid;place-items:center;font-size:24px;background:#126dff}.metric.green{border-color:#079c68}.metric.green span{background:#08764e}.metric.amber{border-color:#c5821b}.metric.amber span{background:#986016}.metric b{font-size:20px}.metric small{color:#b9cfe0}.workspace{display:grid;grid-template-columns:minmax(680px,1.45fr) minmax(360px,.75fr);gap:14px}.panel,.detail{border:1px solid #21608a;border-radius:9px;background:#001522;overflow:hidden}.table-panel{overflow:auto}table{width:100%;border-collapse:collapse}th{text-align:left;color:#7dcaff;background:#03243a;padding:10px;font-size:11px}td{padding:11px 10px;border-bottom:1px solid #123b57;white-space:nowrap}td:first-child a{display:grid;grid-template-columns:38px 1fr;grid-template-rows:1fr 1fr}.appicon{grid-row:1/3;width:31px;height:31px;border-radius:5px;background:#0c80e8;display:grid;place-items:center}td small{display:block;color:#91adc1}.selected{background:#073152}.status{display:inline-block;border:1px solid;border-radius:5px;padding:5px 8px;font-weight:700}.status.good{background:#00663f;border-color:#0c9e67}.status.warn{background:#6d4911;border-color:#c88a27}.detail{padding:16px}.detail-head{display:flex;gap:12px;align-items:center;border-bottom:1px solid #24516c;padding-bottom:13px}.bigicon{width:58px;height:58px;border-radius:9px;background:#087fff;display:grid;place-items:center;font-size:30px}.detail-head h2{margin:0;font-size:24px}.detail-head .status{margin-left:auto}.facts{display:grid;grid-template-columns:repeat(2,1fr);margin:10px 0}.facts div{padding:8px;border-right:1px solid #173f58}.facts small,.facts b{display:block}.facts small{color:#7fa7c2;font-size:10px}.tabs{display:flex;gap:18px;border-bottom:1px solid #24516c;padding:10px 0}.tabs b{color:#62c6ff;border-bottom:2px solid #2aa8ff;padding-bottom:8px}.detail h3,.panel h3{font-size:14px}.req{display:grid;grid-template-columns:1fr auto 28px;gap:8px;padding:9px;border-bottom:1px solid #143b55}.req small{display:block;color:#8daabd}.req code{color:#80d5ff}.req i{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-style:normal}.req i.ok{background:#08764e}.req i.bad{background:#986016}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}.actions a{border:1px solid #22638d;padding:9px;text-align:center;border-radius:5px}.lower{display:grid;grid-template-columns:1.2fr .8fr;gap:14px;margin-top:14px}.lower .panel{padding:12px}.activity-row{display:grid;grid-template-columns:16px 1fr auto;gap:8px;padding:7px;border-bottom:1px solid #153b53}.activity-row i,footer i{width:10px;height:10px;border-radius:50%;background:#20d789}.activity-row small{display:block;color:#8caabd}.activity-row time{color:#7bbfe8;font-size:11px}.quick{display:grid;grid-template-columns:1fr 1fr;gap:8px}.quick a{border:1px solid #1f5c83;border-radius:5px;padding:9px;display:flex;gap:8px}.quick small{display:block;color:#91adc1}footer{height:42px;display:flex;align-items:center;gap:15px;padding:0 42px;border-top:10px solid var(--purple);color:#55bfff;font-size:12px}footer b{color:white}.footright{margin-left:auto;display:flex;align-items:center;gap:7px}.empty{padding:20px;color:#8faabd;text-align:center}dialog{background:#001827;color:white;border:1px solid #2c7bab;border-radius:10px;max-width:520px;padding:22px}dialog::backdrop{background:#000a}.muted{color:#8faabd}@media(max-width:1100px){.topbar{grid-template-columns:60px 1fr 110px 170px}.org,.user{display:none}.workspace{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){body{padding:0}.topbar{height:68px;grid-template-columns:45px 1fr 85px}.brand strong{font-size:22px}.brand small,.clock{display:none}.gear{font-size:34px}.site{font-size:12px;padding:9px}.frame{margin:0;border-radius:0;grid-template-columns:58px 1fr}.sidebar:before{height:20px}.sidebar a{font-size:0;padding:14px 10px}.sidebar a span{font-size:23px}.sidefoot{display:none}main{padding:8px}.metrics{grid-template-columns:1fr 1fr}.toolbar{flex-wrap:wrap}.toolbar input{min-width:100%}.lower{grid-template-columns:1fr}.facts{grid-template-columns:1fr}footer{padding:0 10px}.footright{display:none}}
""";
}
